// Test sort logic: ascending order should have smallest first
void main() {
  // Test cases: prices as strings
  List<String> prices = ['100', '50', '200', '75', '', '25'];

  prices.sort((a, b) {
    final x = a, y = b;
    if (x.isEmpty != y.isEmpty) return x.isEmpty ? 1 : -1;
    final nx = num.tryParse(x), ny = num.tryParse(y);
    final c = (nx != null && ny != null) ? nx.compareTo(ny) : x.compareTo(y);
    if (c != 0) return c;
    return 0;
  });

  print('Sorted: $prices');
  // Expected: [25, 50, 75, 100, 200, ] (empty last)
}
EOF
